import {t as translateText} from './lab-language.js';
import {tempoInfo} from './studio-tempo.js';
import {musicTail} from './music-fx.js';
const clone=x=>JSON.parse(JSON.stringify(x));
export const RELEASE='1.7.2';
export function frozenTake(bench,label,config,extra={}){return clone({bench,label,config,...extra});}
export function nmrComparison(config,kind){const a=clone(config),b=clone(config),bpm=tempoInfo(config).bpm;for(const c of [a,b])c.tempo={...c.tempo,mode:'fixed',bpm,sync:false};let title,changes,observe,labels;
 let holds='Initial state, circuit, readout, acquisition window, audio duration, tuning, level, seed, musical BPM and pulse envelope.';
 if(kind==='t2'){title='T₂ / T₂*';a.echo=b.echo=false;a.qubits.forEach(q=>q.star=q.t2);changes='Only additional Gaussian static frequency spread; echo is off in both halves.';observe='B loses transverse signal faster when T₂* < T₂. Irreversible T₂ loss remains in both. Use transverse FID, not population tones, to study this loss.';labels=['A · homogeneous T₂','B · T₂* with static spread'];}
 else if(kind==='echo'){title='Free FID / Hahn echo';a.echo=false;b.echo=true;changes='Only ideal simultaneous Xπ refocusing pulses at τ.';observe='Static offsets refocus at 2τ. Irreversible T₂ loss and ZZ coupling remain; this is not quantum error correction.';labels=['A · free FID','B · Hahn echo'];}
 else if(kind==='fx'){title='Dry / creative texture';a.fx=0;b.fx=b.fx||.5;changes='Only classical creative texture strength.';observe='Compare timbre. Texture is an artistic audio process, not a calibrated noise bath.';labels=['A · dry','B · creative texture'];}
 else if(kind==='tuning'){title='12-TET / selected tuning';a.tuning='equal';changes='Only musical carrier tuning.';holds=holds.replace('tuning','root and sonification object');observe='Compare intervals and beating. Quantum evolution remains identical.';labels=['A · 12-TET','B · '+b.tuning];}
 else if(kind==='tempo'){title='Fixed / model-linked rhythm';a.version=b.version=5;a.tempo={...a.tempo,bpm:Math.min(180,Math.max(120,config.tempo.bpm)),rhythm:true};b.tempo={...b.tempo,mode:'model',rhythm:true};changes='Only musical BPM: fixed versus the selected model-time mapping.';holds=holds.replace('musical BPM and pulse envelope','pulse depth and shape');observe='Listen to pulse speed. This creative gain envelope is not a nuclear precession frequency.';labels=['A · fixed BPM','B · model-linked BPM'];}
 else throw Error('Unknown comparison');return {bench:'studio',title,changes,holds,observe,segments:[frozenTake('studio',labels[0],a),frozenTake('studio',labels[1],b)]};}
export function musicComparison(config,sequence,kind){const a=clone(config),b=clone(config);if(kind!=='fx')a.tuning='equal';return {bench:'music',title:kind==='fx'?'Clean / Processed':'12-TET / selected tuning',changes:kind==='fx'?'Only classical FX processing. Clean bypasses the rack, retaining oscillator and filter.':'Only musical tuning.',holds:'Circuit, readout, probabilities, seed, outcomes, oscillator, filter, level, BPM, note length and number of loops.',observe:kind==='fx'?'Compare timbre and tails. No loudness matching is applied; louder audio is not quantum amplification.':'Compare carrier intervals for exactly the same outcomes; the quantum state does not change.',segments:[frozenTake('music',kind==='fx'?'A · Clean':'A · 12-TET',a,{sequence,variant:kind==='fx'?'clean':'processed'}),frozenTake('music',kind==='fx'?'B · Processed':'B · '+b.tuning,b,{sequence,variant:'processed'})]};}
export function takeDuration(t){if(t.segments)return t.segments.reduce((n,s)=>n+takeDuration(s),0)+.15*(t.segments.length-1);const c=t.config;if(t.bench==='studio')return Math.round(c.duration*44100)/44100;const n=t.sequence?.length||16,d=n===1?.5:n*c.exportLoops*60/c.bpm/c.division;return Math.round((d+musicTail(c,t.variant||'processed').tail)*44100)/44100;}
export function takeSummary(t,format='WAV'){if(t.segments)return `${t.title} · A → 0.15 s silence → B · ${takeDuration(t).toFixed(2)} s · ${format}`;const c=t.config;if(t.bench==='music')return `${t.label} · ${t.variant==='clean'||c.fx.bypass?'Clean':'Processed'} · ${c.bpm} BPM · ${takeDuration(t).toFixed(2)} s · ${format}`;const q=tempoInfo(c);return `${t.label} · ${c.fx?'Processed':'Dry'} · Pulse ${q.rhythmEnabled?'on':'off'} · ${q.bpm.toFixed(2)} BPM · ${c.duration} s · ${format}`;}
export function descriptionText(t){return ['Quantum Music Studio · '+RELEASE,takeSummary(t),'',`What changes: ${t.changes||'Current frozen configuration; no isolated A/B variable is asserted.'}`,`Held fixed: ${t.holds||'The captured settings, sequence and seed below.'}`,`Observe: ${t.observe||'Listen to the selected classical sonification of a simulated state or signal.'}`,'',`Total audio duration: ${takeDuration(t).toFixed(6)} s`,t.segments?'Order: A, 0.15 seconds of silence, B. Each segment restarts from its initial state.':'Playback/export restarts this frozen version from the beginning.','Reference A4 = 435 Hz. Stereo 44.1 kHz. WAV PCM16; MP3 128 kbps (encoder padding may extend decoded duration).','Live slider automation and previous live FX memory are not recorded in a frozen export.','Clean bypasses FX only; Clean sine is a separate preset changing oscillator/filter/level.','NMR times are illustrative unless explicitly calibrated. Physical acquisition time and audio seconds are separate.','120 + 60/(1+T/Tref) is a creative BPM mapping. Decay/echo A/B freezes BPM and pulse depth.','Spin echo refocuses static spread, not irreversible T2 loss. Reverb/delay are classical DSP.','No hardware acquisition or entanglement certification is implied.','','Frozen settings and sequence:',JSON.stringify(t,null,2)].map(line=>line.startsWith('{')?line:translateText(line)).join('\n');}
export function announceTake(t){document.dispatchEvent(new window.CustomEvent('lab:take',{detail:clone(t)}));}
